-- Managed Boats: the client's RYA inspection checklists, and inventory matching.
--
-- 29 Sep 2026. The three RYA lists (Personal Water Craft / Powerboat / Cruising)
-- come from the operations team's "OPS Checklist.xlsx", item for item, keeping
-- the sheet's section, quantity/unit and RYA TC reference. The generic starter
-- items from 20260929140000 are removed; DMA and FMA stay empty until the
-- official lists arrive. Each boat's tick can also be linked to the inventory
-- row that satisfies it.

alter table public.orbit2_checklist_templates
  add column if not exists section text,
  add column if not exists qty     numeric,
  add column if not exists unit    text,
  add column if not exists ref     text;

alter table public.orbit2_boat_checklist
  add column if not exists inventory_item_id uuid references public.orbit2_boat_inventory(id) on delete set null;

-- Placeholders out (nothing has been ticked against them yet).
delete from public.orbit2_checklist_templates;

